# 1. Standard Whitelisted API (Logged-in users only):
@frappe.whitelist()
def get_user_stats(user_id):
    return {
        "open_tickets": frappe.db.count("Issue", {"raised_by": user_id, "status": "Open"}),
        "last_login": frappe.db.get_value("User", user_id, "last_login")
    }

# 2. Public API accessible by guest (unauthenticated) users with POST method restriction:
@frappe.whitelist(allow_guest=True, methods=["POST"])
def submit_contact_inquiry(full_name, email, message):
    lead = frappe.get_doc({
        "doctype": "Lead",
        "lead_name": full_name,
        "email_id": email,
        "notes": message
    })
    lead.insert(ignore_permissions=True)
    return {"status": "success", "lead": lead.name}

