Document.example:
def validate(self):
    if self.from_date > self.to_date:
        frappe.throw("From Date cannot be after To Date!")

class PurchaseOrder(Document):
    def validate(self):
        if self.is_new():
            frappe.msgprint("Welcome! Creating a brand new Purchase Order.")
        else:
            frappe.msgprint("Editing an existing Purchase Order record.")

class Customer(Document):
    def validate(self):
        if self.has_value_changed("credit_limit"):
            frappe.msgprint(f"Credit limit updated to {self.credit_limit}. Emailing financial controller.")

class SalesOrder(Document):
    def validate(self):
        old_doc = self.get_doc_before_save()
        if old_doc and old_doc.delivery_status != self.delivery_status:
            frappe.msgprint(f"Delivery status changed from {old_doc.delivery_status} to {self.delivery_status}")

frappe.model.naming.example:
# Used inside on_trash() or on_cancel() hooks:
from frappe.model.naming import revert_series_if_last

class SalesInvoice(Document):
    def on_trash(self):
        # Revert counter if this invoice was the last one generated
        if self.naming_series:
            prefix = self.naming_series.replace(".#####", "")
            revert_series_if_last(prefix, self.name)

from frappe.model.naming import set_name_by_naming_series

class CustomDoc(Document):
    def autoname(self):
        set_name_by_naming_series(self)

