# 2. Cache-aside pattern with automatic generator on cache miss:
def calculate_sales():
    return frappe.db.sql("SELECT sum(grand_total) FROM `tabSales Invoice` WHERE status='Paid'", as_dict=True)

stats = frappe.cache.get_value("paid_sales_total", generator=calculate_sales, expires_in_sec=3600)
